SQL_DOC.P_SQL:
SELECT NVL(B.STATUS ,' ') AS STATUS, NVL(B.BUYER ,' ') AS BUYER, NVL(B.PO_NO ,' ') AS PO_NO, NVL(B.PO_SEQ ,' ') AS PO_SEQ, NVL(B.LEGACY_PO_NO ,' ') AS LEGACY_PO_NO, NVL(SUBSTR(B.LEGACY_PO_SEQ,1,10) ,' ') AS LEGACY_PO_SEQ1, NVL(B.LEGACY_PO_SEQ ,' ') AS LEGACY_PO_SEQ, NVL(SUBSTRB(B.LEGACY_PO_SEQ, 1, INSTRB(B.LEGACY_PO_SEQ, '-', 1, 1) - 1),' ') AS PO_LINE_NO, NVL(SUBSTRB(B.LEGACY_PO_SEQ, INSTRB(B.LEGACY_PO_SEQ, '-', 1, 1) +1, LENGTH(B.LEGACY_PO_SEQ) ),' ') PO_SHIPMENT_ID, NVL(MAX(C.COM_NAME_LOC),' ') AS SELLER_NAME, NVL(SUBSTRB(C.TEL_NO, 1, INSTRB(C.TEL_NO, '-', 1, 1) - 1),' ') || NVL(SUBSTRB(C.TEL_NO, INSTRB(C.TEL_NO, '-', 1, 1) + 1, INSTRB(C.TEL_NO, '-', 1, 2) - INSTRB(C.TEL_NO, '-', 1, 1) - 1),' ') || NVL(SUBSTRB(C.TEL_NO, INSTRB(C.TEL_NO, '-', 1, 2) + 1, 4),' ') AS SELLER_TELNO, NVL(MAX(SUBSTRB(D.USER_NAME_LOC,1,10)), ' ') AS SELLER_PERSON_NAME, (SELECT NVL(MIN(T.DS_DATE),'X') FROM ICOMPORS T WHERE T.BUYER = B.BUYER AND T.PO_NO = B.PO_NO AND T.PO_SEQ= B.PO_SEQ AND T.STATUS ^= 'D') AS DS_DATE FROM ICOMPOHD A, ICOMPODT B, ICOMCMPY C, ICOMLUSR D WHERE A.BUYER = '$G_RS.BUYER$' AND A.PO_NO = '$G_RS.PO_NO$' AND B.BUYER = A.BUYER AND B.PO_NO = A.PO_NO AND A.AGENT = C.COM_CODE AND C.COM_CODE = D.COM_CODE GROUP BY B.STATUS,B.BUYER,B.PO_NO,B.PO_SEQ,B.LEGACY_PO_NO,B.LEGACY_PO_SEQ,A.AGENT,C.TEL_NO
DECLARE
V_SEND_DATE ICOMPORS.SEND_DATE%TYPE; V_SEND_TIME ICOMPORS.SEND_TIME%TYPE; V_SEND_DATETIME ICOMTRXL.KEY_8%TYPE;
BEGIN
SELECT TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') INTO V_SEND_DATE, V_SEND_TIME, V_SEND_DATETIME FROM DUAL;
IF '$G_RS.KEY_10$' = 'RS' THEN UPDATE ICOMPORS SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND PO_NO = '$G_RS.PO_NO$'; ELSE
UPDATE ICOMPOHD SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND PO_NO = '$G_RS.PO_NO$';
UPDATE ICOMPODT SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND PO_NO = '$G_RS.PO_NO$'; END IF;
UPDATE ICOMTRXL SET KEY_9 = 'D', KEY_8 = V_SEND_DATETIME WHERE DOC_NAME = 'FASHPO' AND KEY_1 = '$G_RS.BUYER$' AND KEY_2 = '$G_RS.PO_NO$' AND TRIM(KEY_9) IS NULL ;
END;
UPDATE ICOMTRXL SET KEY_9 = 'E', KEY_8 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = 'FASHPO' AND KEY_1 = '$G_RS.BUYER$' AND KEY_2 = '$G_RS.PO_NO$' AND TRIM(KEY_9) IS NULL
